struct Scene {
    var objects: [Object; 256]
    var lights: [Light; 16]
    var camera: Camera
    var bg: float3
}

@kernel
func raytrace(ray: Ray, scene: Scene) -> float4 {
    var closest = INFINITY
    var hit: HitRecord
    for obj in scene.objects {
        let t = obj.intersect(ray)
        if t < closest {
            closest = t
            hit = obj.hit(ray, t)
        }
    }
    return shade(hit, scene.lights)
}
